/** sort value (+ optional ranks) ⇒ comparator */
function orderBy(sort, ranks) {
  // Write your solution here
  const desc = sort.startsWith('-'), key = sort.replace('-', '');
  return (a, b) => (desc ? -1 : 1) * String(a[key]).localeCompare(String(b[key]));
}

