// Reference solution
function includeLab(page, labs) {
  const byId = new Map(labs.map((l) => [l.id, l]));
  return page.map((b) => {
    const l = byId.get(b.labId);
    return { ...b, lab: l ? { id: l.id, code: l.code, name: l.name } : null };
  });
}
